using VisionFramework;
namespace VisionEditor.Core;
public sealed partial class GraphEditorDocument {
 SolutionDocument PropagateGroupInterface(SolutionDocument document,ProcedureDocument changed,ISet<string>? invalidVariables=null){
  var procedures=document.Procedures.ToDictionary(p=>p.Id,StringComparer.Ordinal);
  void Apply(ProcedureDocument body){var before=procedures[body.Id];procedures[body.Id]=body;if(body.GroupOwner is not {} owner)return;var parent=procedures[owner.ProcedureId];var signature=WorkflowCalls.From(body);var oldSignature=WorkflowCalls.From(before);var inputMapping=oldSignature.Inputs.ToDictionary(p=>p.Name,p=>signature.Inputs.SingleOrDefault(n=>n.Id==p.Id),StringComparer.Ordinal);var oldPorts=oldSignature.Outputs;var mapping=oldPorts.ToDictionary(p=>p.Name,p=>signature.Outputs.SingleOrDefault(n=>n.Id==p.Id),StringComparer.Ordinal);
   // Derived leaves retain their root interface identity during rename/removal.
   foreach(var oldPort in oldPorts){var updated=mapping[oldPort.Name];foreach(var leaf in CompoundOutputFields.Leaves(oldPort.Kind,oldPort.Cardinality)){var next=updated is null?null:CompoundOutputFields.Leaves(updated.Kind,updated.Cardinality).SingleOrDefault(l=>l.Path==leaf.Path&&l.Kind==leaf.Kind&&l.Cardinality==leaf.Cardinality);mapping[oldPort.Name+"."+leaf.Path]=next is null?null:new WorkflowCallPort(oldPort.Id+"."+leaf.Path,updated!.Name+"."+leaf.Path,next.Kind){Cardinality=next.Cardinality};}}
   WorkflowValueReference? Reference(WorkflowValueReference source){
    var mapped=source.Kind==WorkflowSourceKind.NodeOutput&&source.Id==owner.NodeId&&source.Port is {} port&&mapping.TryGetValue(port,out var updated)?updated is null?null:source with{Port=updated.Name}:source;
    if(mapped is null)return null;if(mapped.ArrayIndex?.IndexSource is not {} index)return mapped;
    var remapped=Reference(index);return remapped is null?null:mapped with{ArrayIndex=mapped.ArrayIndex with{IndexSource=remapped}};
   }
   WorkflowInterfaceItem Interface(WorkflowInterfaceItem item){if(item.NodeId!=owner.NodeId||item.Port is null||!mapping.TryGetValue(item.Port,out var updated))return item;return updated is null?item with{NodeId=null,Port=null}:item with{Port=updated.Name,Kind=updated.Kind,Cardinality=updated.Cardinality};}
   GroupBreakBindings? Bindings(GroupBreakBindings? bindings,bool inside){GroupOperand? Operand(GroupOperand? operand){if(operand is null)return null;var source=operand.Inside==inside&&operand.Source is not null?Reference(operand.Source):operand.Source;var index=!inside&&operand.IndexSource is not null?Reference(operand.IndexSource):operand.IndexSource;if(operand.Source is not null&&source is null)return null;return operand with{Source=source,IndexSource=index};}return bindings is null?null:new(Operand(bindings.Left),Operand(bindings.Right));}
   WorkflowRunTarget? ProxyTarget(WorkflowRunTarget target)=>target.NodeId==owner.NodeId&&target.IsInput&&inputMapping.TryGetValue(target.Parameter,out var port)?port is null?null:target with{Parameter=port.Name}:target;
   WorkflowRunParameter? Proxy(WorkflowRunParameter proxy){var target=ProxyTarget(new(proxy.NodeId,proxy.Parameter,proxy.IsInput));return target is null?null:proxy with{Parameter=target.Parameter,Relations=proxy.Relations?.Select(ProxyTarget).Where(t=>t is not null).Select(t=>t!).ToArray()};}
   var configuration=parent.Configuration with{RunParameters=parent.Configuration.RunParameters.Select(Proxy).Where(p=>p is not null).Select(p=>p!).ToArray(),Subscriptions=parent.Configuration.Subscriptions.Where(b=>Reference(b.Source)is not null&&!(b.NodeId==owner.NodeId&&!b.IsParameter&&inputMapping.TryGetValue(b.Target,out var input)&&input is null)).Select(b=>b with{Source=Reference(b.Source)!,Target=b.NodeId==owner.NodeId&&!b.IsParameter&&inputMapping.TryGetValue(b.Target,out var input)&&input is not null?input.Name:b.Target}).ToArray(),Inputs=parent.Configuration.Inputs.Select(Interface).ToArray(),Outputs=parent.Configuration.Outputs.Select(Interface).ToArray(),Displays=parent.Configuration.Displays.Select(Interface).ToArray(),Variables=parent.Configuration.Variables.Select(v=>v.SourceNode==owner.NodeId&&v.SourcePort is {} port&&mapping.TryGetValue(port,out var updated)?v with{SourceNode=updated is null?null:v.SourceNode,SourcePort=updated?.Name}:v).ToArray()};
   var nodes=parent.Nodes.Select(n=>n with{Call=n.Id==owner.NodeId?signature:n.Call,GroupBreak=Bindings(n.GroupBreak,false)}).ToArray();var edges=parent.Connections.Where(e=>e.FromNode!=owner.NodeId||!mapping.TryGetValue(e.FromPort,out var target)||target is not null).Select(e=>e.FromNode==owner.NodeId&&mapping.TryGetValue(e.FromPort,out var target)&&target is not null?e with{FromPort=target.Name}:e).ToArray();
   if(parent.GroupOwner is {} outer){var grand=procedures[outer.ProcedureId];procedures[grand.Id]=grand with{Nodes=grand.Nodes.Select(n=>n.Id==outer.NodeId?n with{GroupBreak=Bindings(n.GroupBreak,true)}:n).ToArray()};}
   Apply(parent with{Nodes=nodes,Connections=edges.Where(e=>e.ToNode!=owner.NodeId||!inputMapping.TryGetValue(e.ToPort,out var input)||input is not null).Select(e=>e.ToNode==owner.NodeId&&inputMapping.TryGetValue(e.ToPort,out var input)&&input is not null?e with{ToPort=input.Name}:e).ToArray(),Configuration=configuration});
  }
  Apply(changed);var result=document with{Procedures=document.Procedures.Select(p=>procedures[p.Id]).ToArray()};if(invalidVariables is {Count:>0})result=ClearInvalidGroupBreakVariables(result,changed.Id,invalidVariables);
  foreach(var next in result.Procedures){var old=document.Procedures.Single(p=>p.Id==next.Id);var oldIssues=GraphValidator.Validate(old,registry).Issues.Select(i=>(i.Code,i.NodeId,i.Message)).ToHashSet();var problem=GraphValidator.Validate(next,registry).Issues.FirstOrDefault(i=>i.Code is "PortType" or "WorkflowConfiguration" or "GroupBreakType" or "GroupBreakSource"&&!oldIssues.Contains((i.Code,i.NodeId,i.Message)));if(problem is not null)throw new InvalidOperationException("接口变更与现有订阅不兼容，请先调整下游绑定："+problem.Message);}
  return result;
 }
}
